   "orig": "Europa League: la Juve sorride a Vigo, Kolo Muani rimonta al 92'",
   "lead": "La Juventus ha battuto il Celta Vigo 2-1 in Europa League, ribaltando il risultato nel finale con la rete di Randal Kolo Muani al 92', dopo il vantaggio firmato da Nick Woltemade. Nella stessa serata il Milan ha travolto 4-0 il Salisburgo in trasferta, grazie alla tripletta di Cisse, restando in dieci uomini dopo l'espulsione di Terracciano nel finale senza che il risultato cambiasse.",
