   "orig": "Fluminense vence Flamengo e abre vantagem na Copa do Brasil Feminina",
   "lead": "Nel primo Fla-Flu valido per i quarti di finale della Copa do Brasil Feminina, il Fluminense ha vinto 2-1 contro il Flamengo giovedì 15 ottobre allo stadio Luso-Brasileiro di Rio de Janeiro. Il ritorno si giocherà sempre a Rio il prossimo giovedì, con il Fluminense che potrà qualificarsi anche con un pareggio, mentre il Flamengo dovrà vincere con almeno due gol di scarto nei tempi regolamentari per evitare i rigori.",
