   "lead": "Le azioni indonesiane sono crollate oltre l'11% dopo che l'indice MSCI ha dichiarato che non è più appropriato mantenere lo status di mercato emergente per il paese, aprendo alla possibilità di una riclassificazione. L'autorità di vigilanza finanziaria indonesiana OJK, tramite la presidente Friderica Widyasari Dewi, ha detto di rispettare il piano di MSCI.",
