   "lead": "Il progetto abitativo Lion Green Road a Coulsdon, nel sud di Londra, firmato dagli studi Mary Duggan Architects e Ruff Architects, ha vinto il RIBA Stirling Prize 2026 come miglior nuovo edificio del Regno Unito. Commissionato dal Croydon Council, il complesso ad alta densità offre 157 abitazioni distribuite in cinque edifici collegati tra loro, su un'ex area di parcheggio, combinando alloggi di proprietà privata e sociale.",
