   "lead": "Secondo Euronews, il collasso totale del ghiacciaio Thwaites, noto come ghiacciaio 'Doomsday', contribuirebbe a un innalzamento stimato di 65 centimetri del livello globale del mare. Lo studio spiega perché il ghiacciaio continuerebbe a sciogliersi anche in scenari di raffreddamento degli oceani, sottolineando che ridurre le emissioni resta comunque importante. Lo riferisce Euronews.",
