   "lead": "Durante un vertice dell'Unione europea la Cechia ha spinto per ottenere un rinvio dell'entrata in vigore dello schema europeo sulle emissioni, facendo emergere divisioni tra i paesi membri sul tema climatico. Lo riferisce Radio Prague International.",
