   "lead": "Il basso volume di scambi di beni tra Barbados e i paesi africani potrebbe essere compensato da nuove opportunità nei servizi digitali, nell'intelligenza artificiale e nel settore farmaceutico, secondo la responsabile dell'agenzia statale di promozione delle esportazioni. La dirigente ha però avvertito che restano da superare vincoli legati a finanziamenti, trasporti marittimi e capacità produttiva. Lo riferisce Barbados Today.",
