   "titolo": "Isabel Allende vince il Premio Planeta 2026 con il seguito de «La casa degli spiriti»",
   "orig": "Terremoto editorial: Isabel Allende gana el Premio Planeta 2026 con la secuela de ‘La casa de los espíritus’",
   "lead": "La scrittrice cilena Isabel Allende, legata alla casa editrice Plaza & Janés dal 1982, ha vinto il Premio Planeta 2026, ottenendo un milione di euro, con un romanzo che è la seconda parte del suo celebre «La casa degli spiriti». Il finalista è stato lo sceneggiatore Sergio Hernández. Secondo La Tercera, il premio è stato consegnato ad Allende dai reali di Spagna durante una cerimonia a Barcellona, e il romanzo vincitore, intitolato «La hora antes del alba», rappresenta una continuazione cronologica della storica opera.",
   "more": [
    "Il Premio Planeta è uno dei riconoscimenti letterari più ricchi e seguiti del mondo ispanofono, assegnato ogni anno in Spagna; «La casa degli spiriti» è il celebre romanzo d'esordio di Isabel Allende, pietra miliare della letteratura latinoamericana contemporanea."
   ],
