   "lead": "Olivia Rodrigo e Chappell Roan compaiono insieme in un game show condotto da David Byrne nel video del remix di «Expectations», brano tratto da «You Seem Pretty Sad for a Girl So in Love». Secondo Billboard, le due pop star hanno raccontato a Zane Lowe l'ispirazione dietro la collaborazione, incluse le storie sentimentali che hanno ispirato il verso scritto da Roan, che ha detto di amare «rendere le cose un po' gay».",
