   "lead": "Gli infermieri dell'ospedale pediatrico Starship di Auckland, in Nuova Zelanda, denunciano a RNZ la peggiore carenza di personale mai vista, con una mancanza di staff esperto in grado di somministrare la chemioterapia: i nuovi laureati, spiegano, non possono colmare il vuoto lasciato dall'esperienza mancante, causando ritardi nei trattamenti oncologici. Lo riferisce RNZ.",
