   "orig": "Lesotho: Is Construction At the Lesotho Highlands Water Project Polluting Rivers?",
   "lead": "Secondo un'inchiesta ripresa da allAfrica, l'autorità per lo sviluppo delle Highlands del Lesotho invierà campioni per analizzare una sospetta inquinamento dei fiumi causato dai lavori di costruzione del grande progetto idrico della regione. Lo riferisce allAfrica.",
