   "lead": "L'Agenzia internazionale per l'energia atomica ha pubblicato un approfondimento sulle tecnologie nucleari applicate allo spazio, dalle batterie nucleari utilizzate nelle missioni spaziali fino ai possibili futuri razzi a propulsione nucleare. Lo riferisce l'Aiea.",
