   "orig": "President hands national flag to 12 athletes headed for Dakar Youth Olympics",
   "lead": "La presidente della Namibia, Netumbo Nandi-Ndaitwah, ha consegnato la bandiera nazionale ai 12 atleti della squadra namibiana che parteciperanno alle Olimpiadi giovanili di Dakar 2026, durante una cerimonia a State House, esortandoli a rappresentare il paese con orgoglio, disciplina e coraggio. Alle stesse Olimpiadi, le prime ospitate sul suolo africano, parteciperà anche l'arbitro del Botswana Kefilwe Rasengwatshe, selezionato per un ruolo ufficiale, un traguardo storico per lo sport del suo paese.",
