   "titolo": "Baked oats con ciliegie morello e mandorle, la ricetta di Helen Goh",
   "orig": "Helen Goh’s recipe for baked oats with morello cherries and almond | The sweet spot",
   "lead": "La cuoca Helen Goh propone sul Guardian una ricetta di baked oats, un dolce a base di avena cotta al forno, con ciliegie morello e mandorle, dolcificato con sciroppo d'acero. Il piatto, ispirato a una ricetta di Heidi Swanson, può essere servito sia a colazione che come dessert. Lo riferisce The Guardian.",
