   "sez": "spazio",
   "titolo": "Le faglie lunari rivelano quanto si sta restringendo la Luna",
   "orig": "Lunar fault maps reveal how much the moon is shrinking",
   "lead": "Un nuovo studio sulle faglie tettoniche più giovani della Luna offre la stima più dettagliata finora disponibile di quanto il nostro satellite si sia contratto nel tempo, man mano che il suo interno si è progressivamente raffreddato. Lo riferisce Phys.org.",
   "more": [
    "Le faglie da compressione sulla superficie lunare testimoniano il lento raffreddamento dell'interno della Luna, che provoca un restringimento del volume del satellite e la formazione di piccole scarpate osservabili dalle missioni orbitali."
   ],
