   "sez": "cultura",
   "titolo": "Fu Hao, la regina guerriera cinese che guidò grandi eserciti",
   "orig": "The ancient Chinese warrior queen who led huge armies to victory and stole a king’s heart",
   "lead": "Fu Hao, una delle prime generali donne documentate della storia, guidò grandi eserciti durante la dinastia Shang, tra il 1600 e il 1046 avanti Cristo, prima dell'unificazione della Cina. Gran parte di ciò che si conosce sulla sua vita proviene dalla sua tomba, scoperta nel 1976, i cui contenuti hanno portato gli archeologi a identificarla come un'alta consorte reale e comandante militare. Lo riferisce South China Morning Post.",
   "more": [
    "La dinastia Shang fu una delle prime dinastie cinesi documentate storicamente, nota per l'uso della scrittura su ossa oracolari; le scoperte archeologiche della sua epoca hanno rivelato un'organizzazione sociale e militare già complessa."
   ],
