   "titolo": "Fondi DM 33 per la cittadinanza ambientale: scadenza il 30 ottobre",
   "orig": "Fondi DM 33 Cittadinanza Ambientale: con Fondazione Fenice per trasformare la sostenibilità ecologica in un’esperienza concreta. Scadenza 30 ottobre.",
   "lead": "L'avviso ministeriale DM n. 33 del 24 febbraio 2026 finanzia progetti scolastici di educazione civica dedicati all'ambiente e allo sviluppo sostenibile, compresa la riqualificazione di spazi per trasformarli in ambienti didattici. Fondazione Fenice offre supporto alle scuole per trasformare la sostenibilità ecologica in un'esperienza concreta. Le candidature devono essere presentate entro le ore 15 del 30 ottobre 2026, prima dell'esaurimento dei fondi disponibili. Lo riferisce Orizzonte Scuola.",
   "more": [
    "I decreti ministeriali come il DM 33 finanziano iniziative scolastiche su temi civici e ambientali, permettendo agli istituti di realizzare progetti didattici e di riqualificazione degli spazi scolastici per promuovere l'educazione alla sostenibilità."
   ],
