   "orig": "Surgery giving Kiwis hope of Ponga playing again in World Cup",
   "lead": "Il fullback neozelandese Kalyn Ponga, rottosi il braccio nella partita d'apertura della Nazionale ai Mondiali di rugby league, è stato sottoposto a un intervento chirurgico nel tentativo di poter tornare in campo durante il torneo. L'operazione alimenta le speranze dei tifosi neozelandesi di rivedere la loro stella in azione nel corso della competizione. Lo riferisce ABC News Australia.",
