   "titolo": "Una joint venture Turner-FH avvia i lavori per un ospedale in Colorado",
   "orig": "Turner-FH joint venture breaks ground on Colorado hospital",
   "lead": "La joint venture formata da Turner e FH ha dato il via ai lavori di costruzione di un nuovo ospedale per il gruppo sanitario AdventHealth a Louisville, in Colorado. Secondo quanto riportato da Becker's Hospital Review, il costo complessivo del progetto ammonta a 475 milioni di dollari. Lo riferisce Construction Dive.",
