   "titolo": "Carney accusa gli USA di voler dividere il Canada, mentre l'Alberta vota sul referendum per l'indipendenza",
   "orig": "Carney says US trying to break Canada amid vote for Alberta independence referendum",
   "lead": "La provincia canadese ricca di petrolio dell'Alberta si prepara a votare per decidere se restare parte del Canada o avviare il percorso legale verso la secessione. Il primo ministro canadese Carney ha accusato gli Stati Uniti di utilizzare una tattica di divisione per cercare di frammentare il Canada in questo contesto. Lo riferisce Deutsche Welle.",
