    "L'Alberta è una provincia occidentale del Canada ricca di risorse petrolifere, storicamente caratterizzata da tensioni politiche con il governo federale di Ottawa su temi economici e fiscali legati all'industria energetica; un eventuale referendum indipendentista avrebbe implicazioni rilevanti sull'unità del Paese."
