   "lead": "Un reportage di Rolling Stone Italia racconta Parigi all'indomani del disastroso incendio che ha sfigurato il Marché des Enfants Rouges, il mercato coperto più antico della città, da sempre meta di gourmand e scrittori. Il pezzo riflette su chi sono e chi sono stati i parigini in rapporto a questo luogo simbolico. Lo riferisce Rolling Stone Italia.",
