   "titolo": "The Lancet pubblica un commento sulle profezie e i rischi globali per la salute",
   "orig": "[Comment] Offline: In praise of astrologers, sorcerers, and magicians",
   "lead": "Un commento su The Lancet riflette sul tema delle profezie come terreno di scontro per il futuro, richiamando il libro \"Prophecy\" di Carissa Véliz pubblicato nel 2026. Il dibattito si è intensificato questa settimana con la pubblicazione di una Commissione su minacce globali alla salute nel 21° secolo, che ha analizzato quasi 400 rischi, identificandone due esistenziali e 15 catastrofici maggiori; il processo di revisione tra pari ha offerto spunti su come tali conclusioni vengano accolte. Lo riferisce The Lancet.",
   "more": [
    "Le commissioni scientifiche come quelle promosse da The Lancet riuniscono esperti per valutare in modo sistematico rischi globali per la salute pubblica, spaziando da minacce ambientali a conflitti e crisi tecnologiche, al fine di orientare politiche di prevenzione a livello internazionale."
   ],
