   "titolo": "Il Canada corteggia partnership commerciali con l'India nella corsa a un accordo di libero scambio",
   "orig": "Canada courting Indian business partnerships in race to seal trade deal",
   "lead": "La più grande missione commerciale canadese in India degli ultimi 30 anni ha portato alla firma di circa 30 accordi commerciali, per un valore complessivo stimato in 300 milioni di dollari. Lo ha dichiarato il ministro canadese per il Commercio Internazionale, Maninder Sidhu, nel contesto dei negoziati in corso per sigillare un più ampio accordo di libero scambio tra i due Paesi. Lo riferisce CBC News.",
