 "contesti": {
  "houthi": "La guerra civile yemenita dura dal 2014: una coalizione guidata dall'Arabia Saudita sostiene il governo riconosciuto contro gli Houthi, alleati dell'Iran, che controllano Sanaa e il Nord del Paese. Il cessate il fuoco Onu in vigore dal 2022 è crollato dopo che le forze governative, con appoggio aereo saudita, hanno lanciato a inizio ottobre un'offensiva per riprendere il controllo dello stretto di Bab el-Mandeb. Da allora gli Houthi rispondono con settimane di missili e droni: l'11 ottobre un attacco a Riyadh ha causato la morte di 12 persone, il più letale sul Regno in oltre un decennio, seguito dai raid su Aramco.",
  "starlink": "Da mesi Washington chiede a Kiev di fermare gli attacchi alle raffinerie russe in cambio del sostegno militare, nel quadro dei negoziati di pace promossi dall'amministrazione Trump dopo l'inizio della sua guerra con l'Iran lo scorso febbraio. Nella notte tra il 13 e il 14 ottobre i terminali Starshield/Starlink usati dall'esercito ucraino hanno smesso improvvisamente di funzionare oltre i 160 km/h: Musk ha attribuito la responsabilità al governo Usa, che controlla il sistema. Zelensky ha reagito annunciando la ripresa degli attacchi alle raffinerie, mentre Reuters ha rivelato che l'ordine di restrizione sarebbe partito proprio dalla Casa Bianca.",
  "marnero": "Da inizio ottobre almeno sette navi mercantili sono state colpite da droni al largo delle coste di Romania e Bulgaria, entrambi membri della Nato, nel Mar Nero già teatro di tensioni legate alla guerra in Ucraina e di ripetuti episodi di interferenza sulle rotte commerciali. La scia di attacchi ha fatto crescere nell'Alleanza il timore che la Russia stia deliberatamente testando la determinazione occidentale a sostenere Kiev, colpendo infrastrutture civili in acque di Paesi Nato senza dichiarare formalmente guerra.",
  "z35c5bc51": "Navai è stato fermato il 13 ottobre mentre entrava in Kazakistan dal Kirghizistan, con l'accusa di traffico di droga. Pochi giorni prima aveva risolto a Mosca una vicenda civile legata a un incidente con la sua auto di lusso avvenuto in maggio.",
  "zaefbf1c6": "Il Fluminense e il Flamengo si sono affrontati nell'andata dei quarti di finale della Copa do Brasil Feminina, con la gara di ritorno in programma la settimana successiva per decidere chi accederà alle semifinali.",
  "istanbulalluvione": "Nelle ultime settimane l'Europa sudorientale e la Turchia sono state colpite da un'instabilità atmosferica anomala, con sistemi temporaleschi che hanno già causato danni in Grecia e nei Balcani. Istanbul, città di circa 16 milioni di abitanti con infrastrutture idriche spesso sotto pressione durante i nubifragi autunnali, era già stata colpita da allagamenti minori nei giorni precedenti, prima dell'ondata di piogge record di oggi.",
  "indonesiahaze": "Da settembre gli incendi stagionali legati alla pratica del disboscamento agricolo si sono intensificati nel Borneo e a Sumatra, alimentati dalla siccità indotta da El Niño. La foschia ha già causato in passato crisi diplomatiche con Singapore e Malesia, che ogni anno denunciano l'inazione indonesiana. Negli ultimi giorni i livelli di inquinamento sono peggiorati sensibilmente, portando a cancellazioni di voli e a polemiche politiche interne.",
  "elninoglobale": "Negli ultimi mesi gli osservatori climatici internazionali hanno registrato la formazione di un nuovo evento El Niño particolarmente intenso nel Pacifico, con temperature oceaniche superficiali in rapido aumento. Gli scienziati avevano già segnalato anomalie termiche globali nel 2026, mentre in Europa un'estate e un autunno estremi hanno messo in difficoltà il settore agricolo, aprendo la strada agli allarmi odierni su siccità e rischio ecologico.",
  "manovrabanche": "Nelle settimane precedenti il governo aveva più volte annunciato l'intenzione di tagliare l'Irpef nella prossima manovra, alimentando aspettative poi disattese per vincoli di bilancio. Le trattative con le parti sociali e il settore bancario erano proseguite in un clima di incertezza, con Bruxelles che intanto concedeva margini di flessibilità sui conti pubblici, in vista della definizione finale della legge di bilancio 2027.",
  "carocarburanti": "Negli ultimi giorni il prezzo del gasolio è salito sensibilmente nel Sud Italia, aggravando le difficoltà di un settore dell'autotrasporto già colpito da margini ridotti e concorrenza estera. Il malcontento, cresciuto parallelamente alle proteste degli ex lavoratori dell'Ilva e di alcune componenti agricole, ha portato il Comitato guidato da Salvatore Bella a organizzare presidi e blocchi stradali in Sicilia e Calabria.",
  "zacharia": "Katie Zacharia era stata nominata pochi giorni fa portavoce della Casa Bianca dall'amministrazione Trump, presentata con un curriculum che includeva riferimenti alla professione legale. Dopo la nomina sono emerse verifiche giornalistiche che non trovavano traccia della sua iscrizione agli ordini degli avvocati negli Stati in cui aveva vissuto, innescando polemiche sulla sua credibilità proprio all'inizio del suo mandato.",
  "letteresospette": "Negli ultimi giorni diversi uffici pubblici statunitensi, inclusi uffici elettorali, hanno segnalato l'arrivo di corrispondenza sospetta contenente polveri non identificate, episodi che richiamano precedenti ondate di invii minacciosi avvenute in passato negli Stati Uniti in periodi di tensione politica. L'FBI e l'Ispettorato postale hanno aperto un'indagine per individuare origine e natura delle sostanze, mentre cresce la preoccupazione per la sicurezza del personale coinvolto.",
  "hormuz": "Negli ultimi mesi le tensioni militari tra Stati Uniti e Iran si sono intensificate, con ripercussioni dirette sul traffico marittimo nello Stretto di Hormuz, snodo cruciale per le esportazioni petrolifere mondiali. Le compagnie di navigazione e le agenzie marittime britanniche hanno registrato un progressivo aumento di incidenti e segnalazioni di attacchi nelle settimane precedenti, un trend che ha raggiunto il suo picco nell'ultima settimana.",
  "myanmarasean": "Nel febbraio 2021 i militari guidati da Min Aung Hlaing rovesciarono il governo civile di Aung San Suu Kyi, scatenando proteste di massa e una repressione sanguinosa che ha innescato una guerra civile diffusa in tutto il Myanmar. L'ASEAN aveva inizialmente escluso i generali dai summit regionali, ma negli ultimi mesi diversi leader hanno ripreso contatti diplomatici con Naypyidaw, nonostante i bombardamenti su aree civili continuino.",
  "teslaroadster": "La seconda generazione della Tesla Roadster era stata annunciata da Elon Musk già nel 2017, con promesse di prestazioni estreme, ma la produzione ha subito ripetuti ritardi negli anni successivi. Nel frattempo Musk ha più volte collegato il progetto a tecnologie di SpaceX, ipotizzando un pacchetto opzionale con propulsori per migliorare accelerazione e manovrabilità, alimentando attese e scetticismo tra appassionati e analisti del settore automobilistico."
 },
