     "t": "Centra l'ordine di rallentamento partito dalla Casa Bianca secondo Reuters, con dettagli tecnici (160 km/h) e impatto su missioni militari. Cita fonti Difesa ucraina, Beskrestnov e il post di Musk, aggiungendo contesto su tensioni Trump-Zelensky e Patriot in esaurimento.",
