     "t": "Mette al centro la ripresa dei raid ucraini sulle raffinerie russe decisa da Zelensky, definita una sfida a Trump, elencando le 'circostanze allarmanti' (Patriot, Starshield, intelligence). Cita Zelensky ('è finita, basta così') e Musk sulla responsabilità del Pentagono/Trump.",
