     "t": "Riporta le dichiarazioni del premier singaporiano Lawrence Wong, che annuncia indagini su aziende responsabili degli incendi e possibili azioni legali tramite il Transboundary Haze Pollution Act. Attribuisce la foschia a un El Nino intenso e a settimane di fumo su Singapore e Malesia.",
