     "t": "Si concentra sulla polemica attorno al governatore Rudy, fotografato a Singapore durante il Gran Premio F1 mentre la sua provincia soffoca nella foschia. Cita dati ministeriali (277.075 casi respiratori al 12 ottobre) e la difesa ufficiale secondo cui il viaggio era per un controllo medico, autorizzato dal ministro Tito Karnavian.",
