   "divergono": "The Japan Times mette in primo piano la risposta politica di Singapore, con possibili azioni legali contro aziende indonesiane, mentre VnExpress sposta l'attenzione sulla responsabilità politica interna, criticando il governatore indonesiano Rudy per il viaggio a Singapore. Antara, voce ufficiale indonesiana, riporta solo un disagio operativo (sospensione voli) senza menzionare polemiche o responsabilità. RNZ Pacific amplia il quadro geografico citando impatti anche in Papua Nuova Guinea e misure di contrasto agli incendi, aspetto assente nelle altre testate. Le cifre sanitarie citate da VnExpress non compaiono altrove."
