   "divergono": "ANSA e Il Messaggero riportano entrambi il contributo bancario di 5 miliardi ma differiscono sulle cifre del triennio (ANSA parla di quasi 11 miliardi, Il Messaggero di 10,5 miliardi) e sulle reazioni citate: ANSA cita Salvini e Borghi della Lega, Forza Italia e l'opposizione (Boccia, Bonelli, Lupi), mentre Il Messaggero cita il presidente Abi Patuelli. Il Sole 24 Ore sposta il focus sulle misure per le famiglie e sui dati Istat sul potere d'acquisto, aspetto assente in ANSA e Il Messaggero. Rai News e la Repubblica, leggibili solo in parte, non permettono un confronto completo ma la Repubblica nel titolo definisce la manovra «piccola piccola», giudizio sintetico non presente altrove."
